const { seg, lerp, eo, eio, clamp01 } = kit;
const S = 'stroke:#2A2522;stroke-width:5;stroke-linejoin:round;stroke-linecap:round';
Object.assign(W, {
  // crime icons, base at (0,0)
  iconBag(cls) { return '<g class="' + cls + '"><path d="M-62 0 Q-86 -74 -42 -116 L-24 -134 L-40 -156 H40 L24 -134 L42 -116 Q86 -74 62 0 Z" style="fill:#C99A62;' + S + '"/><path d="M-30 -134 H30" style="fill:none;' + S + '"/><circle cx="0" cy="-60" r="24" style="fill:#E3B341;' + S + '"/><circle cx="0" cy="-60" r="10" style="fill:none;stroke:#B88A33;stroke-width:4"/></g>'; },
  iconSkull(cls) { return '<g class="' + cls + '"><path d="M-62 -96 Q-62 -170 0 -170 Q62 -170 62 -96 Q62 -60 40 -48 V-10 H-40 V-48 Q-62 -60 -62 -96 Z" style="fill:#FFFFFF;' + S + '"/><ellipse cx="-24" cy="-100" rx="16" ry="19" style="fill:#2A2522"/><ellipse cx="24" cy="-100" rx="16" ry="19" style="fill:#2A2522"/><path d="M0 -76 L-9 -60 H9 Z" style="fill:#2A2522"/><path d="M-20 -10 V-30 M0 -10 V-30 M20 -10 V-30" style="fill:none;' + S + '"/></g>'; },
  iconCrown(cls) { return '<g class="' + cls + '"><path d="M-80 0 L-92 -120 L-46 -70 L0 -150 L46 -70 L92 -120 L80 0 Z" style="fill:#E3B341;' + S + '"/><path d="M-80 -24 H80" style="fill:none;' + S + '"/><circle cx="0" cy="-50" r="12" style="fill:#C0392B;' + S + '"/><circle cx="-44" cy="-44" r="8" style="fill:#4DB6AC;stroke:#2A2522;stroke-width:3"/><circle cx="44" cy="-44" r="8" style="fill:#4DB6AC;stroke:#2A2522;stroke-width:3"/></g>'; },
});
kit.scene('crimes', {
  init(kit) {
    let ticks = ''; for (let x = 260; x <= 1660; x += 70) ticks += '<path d="M' + x + ' 720 v' + (x % 350 === 260 % 350 ? 34 : 18) + '" style="fill:none;' + S + '"/>';
    const icon = (fn, cls, x) => '<g transform="translate(' + x + ' 690)">' + W.shadowedIcon(fn(cls)) + '</g>';
    W.shadowedIcon = W.shadowedIcon || ((m) => '<g transform="translate(-12 10)" style="opacity:.0">' + m + '</g>' + m);
    const lab = (txt, cls, x) => '<div style="position:absolute;left:' + x + 'px;top:770px;width:0;display:flex;justify-content:center"><p class="hand-label ' + cls + '" style="position:relative">' + txt + '</p></div>';
    kit.stage.append(kit.h('<div class="ground"><div class="layer crimes-cam"><svg class="art" viewBox="0 0 1920 1080">' + W.bg.paper(W.MOODS.infoPaper) +
      '<g class="crimes-ruler"><path d="M260 720 H1660" style="fill:none;stroke:#2A2522;stroke-width:8;stroke-linecap:round"/>' + ticks + '</g>' +
      '<g transform="translate(480 690)">' + W.iconBag('crimes-i1') + '</g><g transform="translate(880 690)">' + W.iconSkull('crimes-i2') + '</g><g transform="translate(1280 690)">' + W.iconCrown('crimes-i3') + '</g>' +
      '<g class="crimes-bar">' + W.info.arrow(240, 900, 1780, 900) + '</g>' +
      '</svg>' + lab('Theft', 'crimes-l1', 480) + lab('Murder', 'crimes-l2', 880) + lab('Treason', 'crimes-l3', 1280) + '</div>' +
      '<p class="hand-label tag crimes-tag" style="left:1100px;top:120px;font-size:84px">Beyond treason</p></div>'));
    const s = (c) => kit.stage.querySelector(c);
    this.icons = ['.crimes-i1', '.crimes-i2', '.crimes-i3'].map(s); this.labels = ['.crimes-l1', '.crimes-l2', '.crimes-l3'].map(s);
    Object.assign(this, { cam: s('.crimes-cam'), bar: s('.crimes-bar'), tag: s('.crimes-tag'), ruler: s('.crimes-ruler') });
  },
  render(t) {
    const hit = 2.08, shake = t > hit ? 10 * Math.exp(-(t - hit) * 9) * Math.sin((t - hit) * 50) : 0;
    this.cam.style.transformOrigin = '960px 600px';
    this.cam.style.transform = 'translate(' + shake.toFixed(1) + 'px,0) scale(' + lerp(1.0, 1.04, eio(seg(t, 0, 3.6))).toFixed(4) + ')';
    // icons pop left to right as 'reserved for crimes' is spoken
    [0.5, 0.9, 1.3].forEach((t0, i) => { W.pop(this.icons[i], t, t0, 'bottom'); W.pop(this.labels[i], t, t0 + 0.08, 'center'); });
    // the coral bar shoots past treason on 'beyond'
    const p = eio(seg(t, 1.7, 2.08));
    this.bar.style.transformBox = 'fill-box'; this.bar.style.transformOrigin = '0% 50%';
    this.bar.style.transform = 'scaleX(' + Math.max(0.001, p).toFixed(3) + ')';
    this.bar.style.opacity = t < 1.7 ? 0 : 1;
    W.pop(this.tag, t, 2.1, 'left');
  },
});
